import type { ScaffoldContentContract } from './scaffoldSchema';

/**
 * Seventy-five authored recipes on ten reusable interaction families.
 * A recipe is a learning/mission specification, not a claim of a distinct engine.
 * Age settings are editable product defaults, never a diagnosis of ability.
 */
export type ScaffoldFamily = 'recall' | 'match' | 'sequence' | 'sort' | 'cloze' | 'scenario' | 'diagram' | 'explain' | 'connect' | 'timed';
export type AgeGroupId = '3-5' | '6-8' | '9-11' | '12-14' | '15-17' | 'adult';

export interface Scaffold {
  version: '1.0.0';
  domain: string;
  contentContract: ScaffoldContentContract;
  id: string;
  name: string;
  tagline: string;
  description: string;
  icon: string;
  family: ScaffoldFamily;
  ages: string[];
  skills: string[];
  mechanic: string;
  learningPrinciple: string;
  missionTemplate: string;
  feedbackRules: string[];
  prerequisites: string[];
  difficulty: 1 | 2 | 3;
  duration: number;
  color: string;
  visual: { scene: 'islands' | 'observatory' | 'forest' | 'workshop' | 'ocean' | 'library'; accent: string; motif: string };
  dialogue: { intro: string; success: string; tryAgain: string; hint: string };
}

export interface AgeGroup {
  id: AgeGroupId;
  label: string;
  title: string;
  description: string;
  recommendedSettings: {
    sessionMinutes: number;
    choices: number;
    maxInstructionsPerStep: number;
    narration: boolean;
    caregiver: boolean;
    timer: boolean;
    competition: 'cooperative' | 'optional';
    scaffolding: 'guided' | 'supported' | 'independent';
  };
}

