export function scaffoldById(id: string): Scaffold | undefined {
  return SCAFFOLDS.find((scaffold) => scaffold.id === id);
}

/** Only ranks the catalog. The compiler must separately validate content prerequisites. */
export function recommendScaffolds(ageGroup: string, skills: string[] = [], limit = 6): Scaffold[] {
  const desired = new Set(skills.map((skill) => skill.trim().toLowerCase()));
  const group = AGE_GROUPS.some((item) => item.id === ageGroup) ? ageGroup : 'adult';
  return SCAFFOLDS.filter((scaffold) => scaffold.ages.includes(group))
    .map((scaffold, index) => ({ scaffold, index, score: scaffold.skills.reduce((score, skill) => score + (desired.has(skill) ? 3 : 0), 0) + (scaffold.ages.length === 1 ? 1 : 0) }))
    .sort((a, b) => b.score - a.score || a.index - b.index)
    .slice(0, Math.max(0, Math.floor(limit)))
    .map(({ scaffold }) => scaffold);
}
